package com.chubb.apac.claims.modulith.claim.service;
import com.chubb.apac.claims.modulith.claim.mapper.ClaimMapper;import com.chubb.apac.claims.modulith.claim.model.*;import com.chubb.apac.claims.modulith.claim.repository.*;import com.chubb.apac.claims.modulith.claim.service.impl.ClaimServiceImpl;import com.chubb.apac.claims.modulith.common.enums.*;import com.chubb.apac.claims.modulith.common.exception.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.context.ApplicationEventPublisher;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ClaimServiceImplTest {@Mock ClaimRepository claims;@Mock ClaimStatusHistoryRepository history;@Mock ClaimAssignmentRepository assignments;@Mock ApplicationEventPublisher events;ClaimServiceImpl service;@BeforeEach void setup(){service=new ClaimServiceImpl(claims,history,assignments,new ClaimMapper(),events);}
 @Test void assignsClaimAtomically(){Claim c=new Claim();c.setClaimId("CLM-1");c.setStatus(ClaimStatus.REPORTED);c.setMarket(Market.SG);when(claims.findForUpdate("CLM-1",Set.of(Market.SG))).thenReturn(Optional.of(c));var out=service.assignToSelf(Set.of(Market.SG),"S1","CLM-1","C1");assertThat(out.assignedStaffId()).isEqualTo("S1");assertThat(c.getStatus()).isEqualTo(ClaimStatus.UNDER_REVIEW);verify(assignments).save(any());}
 @Test void rejectsAlreadyAssignedClaim(){Claim c=new Claim();c.setClaimId("CLM-1");c.setAssignedStaffId("S2");c.setMarket(Market.SG);when(claims.findForUpdate("CLM-1",Set.of(Market.SG))).thenReturn(Optional.of(c));assertThatThrownBy(()->service.assignToSelf(Set.of(Market.SG),"S1","CLM-1","C1")).isInstanceOf(ConflictException.class);}
 @Test void hidesClaimOutsideMarket(){when(claims.findByClaimIdAndMarketIn("CLM-1",Set.of(Market.SG))).thenReturn(Optional.empty());assertThatThrownBy(()->service.getForStaff(Set.of(Market.SG),"CLM-1")).isInstanceOf(ResourceNotFoundException.class);}}
